import { createHmac, timingSafeEqual } from 'crypto'
export async function POST({ request, locals }: { request: Request; locals: { safeGetSession: () => Promise<{ session: unknown }> } }) {
  const { session } = await locals.safeGetSession()
  if (!session) return new Response('no', { status: 401 })
  const body = await request.text()
  const computed = Buffer.from(createHmac('sha256', 'k').update(body).digest('base64'))
  const given = Buffer.from(request.headers.get('sig') ?? '')
  if (computed.length !== given.length || !timingSafeEqual(computed, given)) return new Response('no', { status: 401 })
  return new Response('ok')
}

